// MsgServer is the server API for Msg service.
type MsgServer interface {
	// RegisterHardwareWallet registers a new hardware wallet
	RegisterHardwareWallet(context.Context, *MsgRegisterHardwareWallet) (*MsgRegisterHardwareWalletResponse, error)
	// CreateMultiSigWallet creates a new multi-signature wallet
	CreateMultiSigWallet(context.Context, *MsgCreateMultiSigWallet) (*MsgCreateMultiSigWalletResponse, error)
	// SignMultiSigTransaction signs a pending multi-sig transaction
	SignMultiSigTransaction(context.Context, *MsgSignMultiSigTransaction) (*MsgSignMultiSigTransactionResponse, error)
	// ConfigureSocialRecovery configures social recovery for a wallet
	ConfigureSocialRecovery(context.Context, *MsgConfigureSocialRecovery) (*MsgConfigureSocialRecoveryResponse, error)
	// InitiateRecovery initiates a social recovery process
	InitiateRecovery(context.Context, *MsgInitiateRecovery) (*MsgInitiateRecoveryResponse, error)
	// ApproveRecovery approves a recovery request as a guardian
	ApproveRecovery(context.Context, *MsgApproveRecovery) (*MsgApproveRecoveryResponse, error)
	// ExecuteRecovery executes an approved recovery request
	ExecuteRecovery(context.Context, *MsgExecuteRecovery) (*MsgExecuteRecoveryResponse, error)
	// SimulateTransaction simulates a transaction before execution
	SimulateTransaction(context.Context, *MsgSimulateTransaction) (*MsgSimulateTransactionResponse, error)
	// VerifyDomain verifies a domain for phishing protection
	VerifyDomain(context.Context, *MsgVerifyDomain) (*MsgVerifyDomainResponse, error)
	// SetSpendingLimit sets spending limits for a wallet
	SetSpendingLimit(context.Context, *MsgSetSpendingLimit) (*MsgSetSpendingLimitResponse, error)
	// ConfigureSession configures wallet session settings
	ConfigureSession(context.Context, *MsgConfigureSession) (*MsgConfigureSessionResponse, error)
	// LockSession locks the current wallet session
	LockSession(context.Context, *MsgLockSession) (*MsgLockSessionResponse, error)
	// UnlockSession unlocks a locked wallet session
	UnlockSession(context.Context, *MsgUnlockSession) (*MsgUnlockSessionResponse, error)
	// EnrollBiometric enrolls biometric authentication
	EnrollBiometric(context.Context, *MsgEnrollBiometric) (*MsgEnrollBiometricResponse, error)
	// AuthenticateBiometric authenticates using biometric
	AuthenticateBiometric(context.Context, *MsgAuthenticateBiometric) (*MsgAuthenticateBiometricResponse, error)
	// StoreInSecureEnclave stores key material in secure enclave
	StoreInSecureEnclave(context.Context, *MsgStoreInSecureEnclave) (*MsgStoreInSecureEnclaveResponse, error)
	// CreateEncryptedBackup creates an encrypted backup of seed phrase
	CreateEncryptedBackup(context.Context, *MsgCreateEncryptedBackup) (*MsgCreateEncryptedBackupResponse, error)
	// ConfigureDustFilter configures dust attack filtering
	ConfigureDustFilter(context.Context, *MsgConfigureDustFilter) (*MsgConfigureDustFilterResponse, error)
	// ValidateAddressChecksum validates an address checksum
	ValidateAddressChecksum(context.Context, *MsgValidateAddressChecksum) (*MsgValidateAddressChecksumResponse, error)
}

